// Monta a busca no Drive do Redacted (cofre Obsidian em Meu Drive/Zezinho/Cérebro REDACTED).
// Sem termo (ou "mapa") = abre o "00 Mapa do cérebro", que lista todas as notas.
let termo = String($input.first().json.busca || '').trim().replace(/\.md$/i, '');
if (!termo || /^mapa/i.test(termo)) termo = '00 Mapa do cérebro';
const t = termo.replace(/\\/g, '').replace(/'/g, "\\'");
const q = "(name contains '" + t + "' or fullText contains '" + t + "') and name contains '.md' and trashed = false and mimeType != 'application/vnd.google-apps.folder'";
return [{ json: { termo, q } }];

// Prioriza notas cujo NOME tem o termo; depois as que só citam o termo no texto.
const termo = $('Montar busca').first().json.termo.toLowerCase();
const arquivos = ($input.first().json.files || []).filter(f => f.name.toLowerCase().endsWith('.md'));
const peso = f => { const n = f.name.toLowerCase().replace(/\.md$/, ''); return n === termo ? 0 : n.includes(termo) ? 1 : 2; };
arquivos.sort((a, b) => peso(a) - peso(b));
const escolhidos = arquivos.slice(0, 3);
if (!escolhidos.length) return [{ json: { vazio: true, termo } }];
return escolhidos.map(f => ({ json: { vazio: false, id: f.id, nome: f.name.replace(/\.md$/, ''), atualizado: f.modifiedTime, outros: arquivos.slice(3, 15).map(o => o.name.replace(/\.md$/, '')) } }));

// Junta as notas num texto só para o agente (limite para não gastar tokens à toa).
const escolhidos = $('Escolher até 3 notas').all().map(i => i.json);
const lidos = $input.all().map(i => i.json);
if (escolhidos[0].vazio) {
  return [{ json: { resultado: 'Nenhuma nota encontrada para "' + escolhidos[0].termo + '". Leia o mapa (busca vazia ou "mapa") para ver os nomes das notas e tente de novo com outra palavra.' } }];
}
const MAX_NOTA = 12000;
let texto = '';
escolhidos.forEach((n, i) => {
  let c = String((lidos[i] || {}).conteudo || '');
  if (!c && lidos[i] && lidos[i].error) c = '(erro ao ler: ' + JSON.stringify(lidos[i].error).slice(0, 200) + ')';
  if (c.length > MAX_NOTA) c = c.slice(0, MAX_NOTA) + '\n... (nota cortada)';
  texto += '===== NOTA: ' + n.nome + ' (atualizada ' + String(n.atualizado || '').slice(0, 10) + ') =====\n' + c + '\n\n';
});
const outros = escolhidos[0].outros || [];
if (outros.length) texto += 'Outras notas que também citam o termo: ' + outros.join(', ');
return [{ json: { resultado: texto } }];
